import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { positionLocal, vec3, mix, uniform, smoothstep, uv, length, vec2, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, CircleGeometry, DirectionalLight, Color, Box3, Vector3, DoubleSide } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'orbit-product-hero';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.55, hex: '#101017' }, { at: 1, hex: '#16161d' }],
  };

  const disposables = [];
  const timelines = [];
  const primitiveResults = [];

  // ---- Backdrop stage plane with vertical gradient ----
  const gradStops = colors.gradientStops ?? [{ at: 0, hex: colors.background }, { at: 1, hex: colors.ink }];
  const cBottom = new Color(gradStops[0].hex);
  const cMid = new Color(gradStops[Math.floor(gradStops.length / 2)].hex);
  const cTop = new Color(gradStops[gradStops.length - 1].hex);

  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vUv = uv();
    const lower = mix(vec3(cBottom.r, cBottom.g, cBottom.b), vec3(cMid.r, cMid.g, cMid.b), smoothstep(0.0, 0.55, vUv.y));
    const grad = mix(lower, vec3(cTop.r, cTop.g, cTop.b), smoothstep(0.55, 1.0, vUv.y));
    backdropMat.colorNode = grad;
  }
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Plinth ----
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial();
  plinthMat.roughness = 0.7;
  plinthMat.metalness = 0.3;
  {
    const cA = new Color(colors.background);
    const cB = new Color(colors.ink);
    const h = positionLocal.y.add(0.125).div(0.25);
    plinthMat.colorNode = mix(vec3(cA.r, cA.g, cA.b), vec3(cB.r, cB.g, cB.b), smoothstep(0.0, 1.0, h));
  }
  const plinth = new Mesh(plinthGeo, plinthMat);
  // top face at y=-1.1 -> center at -1.1 - 0.125
  plinth.position.set(0, -1.225, 0);
  root.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // ---- Contact shadow ----
  const shadowGeo = new CircleGeometry(1.6, 64);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  {
    const d = length(uv().sub(vec2(0.5, 0.5))).mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.55);
    shadowMat.colorNode = vec3(0, 0, 0);
    shadowMat.opacityNode = a;
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.34, 0);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- Watch group (orbit + hover target) ----
  const watchGroup = new Group();
  watchGroup.position.set(0, 0, 0);
  root.add(watchGroup);

  const meshUrl = config.meshUrl ?? config.intent?.visualSpec?.meshUrl ?? '/prism-mock/orrery/meshes/watch.glb';
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      const scene = gltf.scene || gltf.scenes?.[0];
      if (!scene) return;

      // apply brushed-metal PBR to meshes
      scene.traverse((o) => {
        if (o.isMesh) {
          const m = new MeshPhysicalNodeMaterial();
          m.roughness = 0.52;
          m.metalness = 0.55;
          m.clearcoat = 0.2;
          m.clearcoatRoughness = 0.4;
          m.color = new Color('#c8ccd2');
          o.material = m;
          disposables.push(m);
        }
      });

      // normalize to 2.2 units tall, centered
      const box = new Box3().setFromObject(scene);
      const size = new Vector3();
      const center = new Vector3();
      box.getSize(size);
      box.getCenter(center);
      const s = size.y > 0 ? 2.2 / size.y : 1;
      scene.scale.setScalar(s);
      scene.position.set(-center.x * s, -center.y * s, -center.z * s);
      // rest on plinth top (y=-1.1) with bottom of mesh
      scene.position.y += -1.1 + (size.y * s) / 2;

      watchGroup.add(scene);

      gsap.fromTo(scene.scale, { x: s * 1.04, y: s * 1.04, z: s * 1.04 },
        { x: s, y: s, z: s, duration: 0.9, ease: 'power4.out' });
    }).catch(() => {});
  }

  // ---- Node-local rim + accent lights ----
  const keyLight = new DirectionalLight(0xffffff, 1.1);
  keyLight.position.set(3, 4, 4);
  root.add(keyLight);

  const rimLight = new DirectionalLight(new Color(colors.accent), 0.8);
  rimLight.position.set(-4, 1.5, 2);
  root.add(rimLight);

  const backRim = new DirectionalLight(0xdfe4ea, 0.5);
  backRim.position.set(-1, 2, -3);
  root.add(backRim);

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  root.add(textGroup);

  const fallback = [
    { text: 'Calibre NA-01', role: 'headline' },
    { text: 'Machined in-house. 41 mm. Grade 5 titanium.', role: 'body' },
    { text: 'FROM 4200 USD / SHIPS IN 21 DAYS', role: 'caption' },
  ];
  const textItems = items.length ? items : fallback;

  for (const item of textItems) {
    const role = item.role || 'body';
    let opts;
    if (role === 'headline') {
      opts = { fontSize: 68, color: colors.paper, align: 'center', maxWidthPx: 900 };
    } else if (role === 'caption') {
      opts = { fontSize: 18, color: colors.accent, align: 'center', letterSpacingPx: 2, maxWidthPx: 900 };
    } else {
      opts = { fontSize: 26, color: colors.paper, align: 'center', maxWidthPx: 900 };
    }
    const t = ctx.fontAtlas.createText(String(item.text ?? ''), opts);
    if (role === 'headline') t.position.set(0, -1.5, 0.1);
    else if (role === 'body') t.position.set(0, -1.9, 0.1);
    else t.position.set(0, -2.15, 0.1);
    textGroup.add(t);
  }

  // entrance
  const enterTl = gsap.timeline();
  enterTl.from(textGroup.position, { y: textGroup.position.y - 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  timelines.push(enterTl);

  // ---- Cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn !== 'function') continue;
    const target = p.name === 'orbit' || p.name === 'depth-rotate' ? watchGroup : root;
    try {
      const res = fn(target, p.params || {});
      if (res) primitiveResults.push(res);
    } catch (e) { /* ignore */ }
  }

  // ---- Hover handlers (drive depth-rotate feel via GSAP tilt) ----
  let hoverTl = null;
  root.userData.handlers = {
    hover: (payload) => {
      const cx = payload?.uv ? (payload.uv.x - 0.5) * 2 : 0;
      const cy = payload?.uv ? (payload.uv.y - 0.5) * 2 : 0;
      const maxRad = (6 * Math.PI) / 180;
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.to(watchGroup.rotation, {
        x: -cy * maxRad,
        z: cx * maxRad * 0.5,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    hoverEnd: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(watchGroup.rotation, { x: 0, z: 0, duration: 0.9, ease: 'power4.out' }, 0);
      hoverTl.fromTo(watchGroup.scale, { x: 1.04, y: 1.04, z: 1.04 },
        { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
    },
    click: () => {
      ctx.emit?.('navigate', { to: 'hub-collection' });
    },
  };

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach((t) => t && t.kill());
    if (hoverTl) hoverTl.kill();
    if (enterTl) enterTl.kill();
    primitiveResults.forEach((r) => { try { r.cleanup?.(); } catch (e) {} });
    disposables.forEach((d) => { try { d.dispose?.(); } catch (e) {} });
    root.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material?.dispose?.();
      }
    });
  };

  return root;
}
